from pathlib import Path
import subprocess,json,hashlib,statistics,time,fcntl
p=Path(__file__).parent;r=Path('/home/reinsirk/Atcoder_Env');old=Path('/tmp/sirkit_lca_20261022')
sha=lambda x:hashlib.sha256(x).hexdigest()
driver=(r/'Verify/current/drivers/lca_main.cpp').read_text();io=(r/'Verify/current/common/fast_io.hpp').read_text();main=driver.replace('#include "Verify/current/common/fast_io.hpp"',io)
variants=['baseline','control','gate_siblings','gate_splithead']; refs={x['case']:dict(x,input=old/'official'/x['case'])for x in json.loads((old/'official_reference.json').read_text())}
for x in json.loads((old/'custom_cases.json').read_text()):refs[x['case']]={'sha256':x['output_sha256'],'input':old/'custom'/x['case']}
cases=['max_random_00.in','max_line_00.in','binary_00.in','path_graph_root_centroid_00.in','almost_line_00.in','star.in','tiny.in','broom.in']
with open('/tmp/sirkit_performance_cpu14.lock','a')as cpu,open('/tmp/atcoder_full_performance_20261018/benchmark.lock','a')as lock:
 fcntl.flock(cpu,fcntl.LOCK_EX);fcntl.flock(lock,fcntl.LOCK_EX)
 for v in variants:
  src=(p/('baseline.hpp'if v=='control'else v+'.hpp')).read_text();(p/(v+'.cpp')).write_text('#define SKIP_RUNTIME_CHECKS\n'+src+main)
  subprocess.run(['taskset','-c','6','/usr/bin/g++','-std=c++23','-O2','-march=native','-DEVAL','-DONLINE_JUDGE',str(p/(v+'.cpp')),'-o',str(p/v)],check=True)
 for v in variants:
  for c,ref in refs.items():
   with ref['input'].open('rb')as f: out=subprocess.check_output(['taskset','-c','6',str(p/v)],stdin=f)
   assert sha(out)==ref['sha256'],(v,c)
 data={v:{c:[]for c in cases}for v in variants}
 for rep in range(9):
  for c in cases:
   for v in variants[rep%4:]+variants[:rep%4]:
    with refs[c]['input'].open('rb')as f:
     t=time.perf_counter_ns();out=subprocess.check_output(['taskset','-c','14',str(p/v)],stdin=f);t=(time.perf_counter_ns()-t)/1e6
    assert sha(out)==refs[c]['sha256'];data[v][c].append(t)
  print('rep',rep,flush=True)
 med={v:{c:statistics.median(xs)for c,xs in cs.items()}for v,cs in data.items()}
 result={'raw':data,'median_ms':med,'ratio':{v:{c:med[v][c]/med['baseline'][c]for c in cases}for v in variants},'body_sha':{v:sha((p/('baseline.hpp'if v=='control'else v+'.hpp')).read_bytes())for v in variants}}
 (p/'gate.json').write_text(json.dumps(result,indent=2));print(json.dumps(result['ratio'],indent=2),flush=True)

