s=s.replace('        int end;','        int end;\n        int head;')
a=s.index('        // uはvの祖先でない。');b=s.index('\n    }',a)
s=s[:a]+'''        while (vertices_[u].head != vertices_[v].head) {
            int uh = vertices_[u].head;
            int vh = vertices_[v].head;
            if (vertices_[uh].depth < vertices_[vh].depth) {
                std::swap(u,v);
                std::swap(uh,vh);
            }
            u = up_[row(uh)];
        }
        return vertices_[u].depth < vertices_[v].depth ? u : v;'''+s[b:]
a='''        levels_ = static_cast<unsigned int>(std::bit_width(static_cast<unsigned int>(maximum_depth)));'''
b='''        std::fill_n(stack, n, -1);
        for (std::size_t i = n; i != 0;) {
            const int v = order[--i];
            const int par = parent[v];
            if (par != -1 && (stack[par] == -1 || vertices_[v].end - vertices_[v].entry > vertices_[stack[par]].end - vertices_[stack[par]].entry)) stack[par] = v;
        }
        for (std::size_t i = 0; i < n; ++i) {
            const int v = order[i];
            vertices_[v].head = parent[v] != -1 && stack[parent[v]] == v ? vertices_[parent[v]].head : v;
