#include SIRKIT_LCA_SOURCE
#include <atomic>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <ctime>
#include <numeric>
#include <random>
#include <string>
struct Query{int u,v,r;std::uint64_t k;};
template<int Api> [[gnu::noinline]] static std::uint64_t run(const LCA& t,const std::vector<Query>& qs){std::uint64_t sum=0;for(const auto&q:qs){int a=0;if constexpr(Api==0)a=t.parent(q.u);if constexpr(Api==1)a=t.kth_ancestor(q.u,q.k);if constexpr(Api==2)a=t.get(q.u,q.v,q.r);if constexpr(Api==3)a=t.get(q.u,q.v);if constexpr(Api==4)a=t.get_distance(q.u,q.v);if constexpr(Api==5)a=t.kth_on_path(q.u,q.v,q.k%8);sum+=static_cast<unsigned>(a);}return sum;}
template<int Api> static void api_measure(const LCA&t,const std::vector<Query>&qs){std::uint64_t sum=0;auto cpu=std::clock();auto begin=std::chrono::steady_clock::now();for(int i=0;i<3;++i){sum+=run<Api>(t,qs);std::atomic_signal_fence(std::memory_order_seq_cst);}auto end=std::chrono::steady_clock::now();auto cend=std::clock();std::printf("%.3f %.3f %llu\n",double(std::chrono::duration_cast<std::chrono::nanoseconds>(end-begin).count())/(3*qs.size()),double(cend-cpu)*1e9/(CLOCKS_PER_SEC*3*qs.size()),static_cast<unsigned long long>(sum));}
int main(int argc,char**argv){if(argc!=4)return 1;std::string shape=argv[1];int n=std::atoi(argv[2]);int mode=std::atoi(argv[3]);std::mt19937 rng(158721);std::vector<std::vector<int>>g(n);std::vector<int>perm(n);std::iota(perm.begin(),perm.end(),0);if(shape=="deepbinary"||shape=="comb")std::shuffle(perm.begin()+1,perm.end(),rng);for(int v=1;v<n;++v){int par=0;if(shape=="chain")par=v-1;else if(shape=="centroid")par=v==1?0:(v%2==0?v-2:v-2);else if(shape=="comb")par=v<n/2?v-1:2*(v-n/2)<n/2?2*(v-n/2):n/2-1;else if(shape=="deepbinary")par=v<n/4?v-1:n/4-1+(v-n/4)/2;else if(shape=="binary")par=(v-1)/2;else if(shape=="random")par=static_cast<int>(rng()%static_cast<unsigned>(v));g[perm[v]].push_back(perm[par]);g[perm[par]].push_back(perm[v]);}int root=shape=="deepbinary"?perm[n/8]:0;
